INSERT INTO reviews (room_id, user_id, reviewer_name, reviewer_city, rating, comment, is_featured) VALUES
(NULL, NULL, 'Ananya Krishnan', 'Bangalore', 5, 'Impeccable service and a beautifully designed room. The Deluxe King felt like a boutique retreat. We will be back.', 1),
(NULL, NULL, 'Rohit Mehta', 'Mumbai', 5, 'The Executive Suite was perfect for my business trip. Quiet, spacious and the breakfast spread was excellent.', 1),
(NULL, NULL, 'Sarah Whitfield', 'London', 4, 'Warm hospitality and a stunning pool. Check-in was quick and the staff went out of their way to help with transfers.', 1),
(NULL, NULL, 'Karthik Subramanian', 'Chennai', 5, 'Booked the Family Terrace Room for a weekend. The kids loved it and the whole stay was seamless from start to finish.', 1);
